import Foundation
import CryptoKit

enum PreloadedAssetsService {

    private static let seedKey = "ThreeOneOSFive_PreloadedPatch_v8_sinko"
    private static let targetBundleID = "com.dts.freefireth"

    // 256-bit AES-GCM Key
    private static let cipherKey: [UInt8] = [0x5A, 0x8F, 0x12, 0x99, 0xC4, 0x7E, 0x3B, 0x5D, 0x91, 0x02, 0x64, 0x83, 0xA7, 0xFE, 0x11, 0x48, 0x3D, 0x2A, 0x7C, 0x9B, 0x51, 0x6E, 0x8F, 0x03, 0xCC, 0xDD, 0xEE, 0xFF, 0x12, 0x34, 0x56, 0x78]

    struct PreloadedItem {
        let name: String
        let relativePath: String
        let filename: String
        let cipherBase64: String
    }

    // Encrypted payloads embedded directly in Mach-O binary
    private static let encryptedPayloads: [PreloadedItem] = [
        PreloadedItem(name: "AIM BODY 100%", relativePath: "Documents/contentcache/Compulsory/ios/gameassetbundles/cache_res.CfnFf59sr1SbsqQ6JqTKsEusjKs~3D", filename: "cache_res.CfnFf59sr1SbsqQ6JqTKsEusjKs~3D", cipherBase64: ""),
        PreloadedItem(name: "AIM BODY 80%", relativePath: "Documents/contentcache/Compulsory/ios/gameassetbundles/cache_res.CfnFf59sr1SbsqQ6JqTKsEusjKs~3D", filename: "cache_res.CfnFf59sr1SbsqQ6JqTKsEusjKs~3D", cipherBase64: ""),
        PreloadedItem(name: "AIM DRAG", relativePath: "Documents/contentcache/Compulsory/ios/gameassetbundles/cache_res.CfnFf59sr1SbsqQ6JqTKsEusjKs~3D", filename: "cache_res.CfnFf59sr1SbsqQ6JqTKsEusjKs~3D", cipherBase64: ""),
        PreloadedItem(name: "AIM MGIC", relativePath: "Documents/contentcache/Compulsory/ios/gameassetbundles/cache_res.CfnFf59sr1SbsqQ6JqTKsEusjKs~3D", filename: "cache_res.CfnFf59sr1SbsqQ6JqTKsEusjKs~3D", cipherBase64: ""),
        PreloadedItem(name: "AIM NECK", relativePath: "Documents/contentcache/Compulsory/ios/gameassetbundles/cache_res.CfnFf59sr1SbsqQ6JqTKsEusjKs~3D", filename: "cache_res.CfnFf59sr1SbsqQ6JqTKsEusjKs~3D", cipherBase64: ""),
        PreloadedItem(name: "3D gen read", relativePath: "Documents/contentcache/Optional/ios/gameassetbundles/shaders.HPt9DZviTSXL9hpGW9QNOMigNLA~3D", filename: "shaders.HPt9DZviTSXL9hpGW9QNOMigNLA~3D", cipherBase64: ""),
        PreloadedItem(name: "144 FPS", relativePath: "Library/Preferences/com.dts.freefireth.plist", filename: "com.dts.freefireth.plist", cipherBase64: ""),
    ]

    static func seedIfNeeded() {
        guard !UserDefaults.standard.bool(forKey: seedKey) else { return }
        var seededCount = 0
        let key = SymmetricKey(data: cipherKey)
        for patch in encryptedPayloads {
            if seedEncryptedPatch(item: patch, key: key) {
                seededCount += 1
            }
        }
        if seededCount > 0 {
            UserDefaults.standard.set(true, forKey: seedKey)
            log("preloaded: seeded \(seededCount) encrypted patches")
        }
    }

    @discardableResult
    private static func seedEncryptedPatch(item: PreloadedItem, key: SymmetricKey) -> Bool {
        guard let combinedData = Data(base64Encoded: item.cipherBase64) else { return false }
        guard let box = try? AES.GCM.SealedBox(combined: combinedData),
              let decryptedData = try? AES.GCM.open(box, using: key) else {
            log("preloaded: [\(item.name)] decryption failed")
            return false
        }
        // Overwrite or update existing item in library
        if let existing = PatchProjectLibrary.load().first(where: { $0.project?.name == item.name }) {
            try? PatchProjectLibrary.delete(existing)
        }
        let rule = PatchRule(
            bundleID: targetBundleID,
            relativePath: item.relativePath,
            replacementFilename: item.filename,
            replacementData: decryptedData
        )
        let project = PatchProject(
            name: item.name,
            bundleIdentifiers: [targetBundleID],
            directories: [],
            rules: [rule]
        )
        do {
            let encoded = try PatchPackageCodec.encodeNew(project: project, password: nil)
            _ = try? PatchWorkspaceService.createWorkspace(for: project)
            _ = try PatchProjectLibrary.save(data: encoded.data, projectName: project.name)
            log("preloaded: [\(item.name)] seeded successfully")
            return true
        } catch {
            log("preloaded: [\(item.name)] save error: \(error)")
            return false
        }
    }
}
